TEST(crestApiTest, parseUrlAcceptsIPv4LiteralAndLocalhost) {
  StringUtils::ParsedUrl loopback =
      StringUtils::parseUrl("http://127.0.0.1:8080/api-v6.0");
  EXPECT_EQ("http", loopback.protocol);
  EXPECT_EQ("127.0.0.1", loopback.host);
  EXPECT_EQ("/api-v6.0", loopback.apipath);
  ASSERT_TRUE(loopback.port.has_value());
  EXPECT_EQ(8080, *loopback.port);

  StringUtils::ParsedUrl named = StringUtils::parseUrl("http://localhost:8080");
  EXPECT_EQ("localhost", named.host);
  EXPECT_EQ("", named.apipath);
  ASSERT_TRUE(named.port.has_value());
  EXPECT_EQ(8080, *named.port);

  // An address with no port gets no default invented for it either.
  EXPECT_FALSE(
      StringUtils::parseUrl("http://127.0.0.1/api-v6.0").port.has_value());

  EXPECT_EQ("http://127.0.0.1:8080/api-v6.0",
            reassemble("http://127.0.0.1:8080/api-v6.0"));
  EXPECT_EQ("https://192.168.1.10:8443/api-v6.0",
            reassemble("https://192.168.1.10:8443/api-v6.0"));
}

