TEST(crestApiTest, getStringOrTest) {
  nlohmann::json js = {{"present", "actual value"},
                       {"presentEmpty", ""},
                       {"nullField", nullptr}};

  // Key absent -> default.
  EXPECT_EQ("fallback", StringUtils::getStringOr(js, "missing", "fallback"));
  // Key present and null -> default (this is the crash nlohmann::json::value()
  // hits instead: type_error.302).
  EXPECT_EQ("fallback", StringUtils::getStringOr(js, "nullField", "fallback"));
  // Key present and non-null -> actual value, default not substituted.
  EXPECT_EQ("actual value",
            StringUtils::getStringOr(js, "present", "fallback"));
  // Key present with an empty (but non-null) value -> the empty value is
  // preserved, not replaced by the default.
  EXPECT_EQ("", StringUtils::getStringOr(js, "presentEmpty", "fallback"));

  // Default argument omitted -> "" fallback.
  EXPECT_EQ("", StringUtils::getStringOr(js, "missing"));
  EXPECT_EQ("", StringUtils::getStringOr(js, "nullField"));
  EXPECT_EQ("actual value", StringUtils::getStringOr(js, "present"));
}
